const classInfo:Record<ClassKey,{label:string;color:string;bg:string}>={S1:{label:"Direkte relevant",color:"#9f2f25",bg:"#f8ddd7"},S2:{label:"Betinget relevant",color:"#9b5b05",bg:"#f9e7bf"},S3:{label:"Normalt ikke relevant",color:"#536258",bg:"#e5ebe6"},SU:{label:"Uavklart",color:"#5f4b8b",bg:"#e9e2f4"}};
function assess(f:Finding,measure:Measure):Assessment{
  if(measure==="general")return{classKey:f.general,explanation:f.explanation.general};
  const text=`${f.name} ${f.latin} ${f.habitat} ${f.dependency}`.toLowerCase();
  const forest=/skog|gran|furu|tre\b|trær|kelo|bark|vedbo|vertstr/.test(text);
  const dead=/død|læger|låg\b|gadd|stubbe|kelo|vedbo|vindfall|tørr/.test(text);
  const lying=/læger|låg\b|liggende/.test(text);
  const standing=/gadd|stående|tørrtr/.test(text);
  const old=/gammel|eldre|kontinuitet|grove|kelo|stabilt skogklima/.test(text);
  const soil=/skogbunn|mykorrh|jord|markbered|kalk|røtter/.test(text);
  const wet=/myr|sump|bekk|elv|vann|hydrolog|fukt/.test(text);
  const living=/levende|vertstr|gamle trær|barlind/.test(text);
  const culture=/jordbruk|åker|eng\b|beite|gård|tun\b/.test(text);
  const mobileObservation=/tretåspett|picoides tridactylus|fossekall|cinclus cinclus/.test(text);
  const unknown=!(forest||dead||old||soil||wet||living||culture);
  const result=(classKey:ClassKey,explanation:string):Assessment=>({classKey,explanation});
  if(culture)return result("S3",`Registrert miljø er normalt ikke knyttet til ${measureInfo[measure].label.toLowerCase()} i skog.`);
  if(unknown)return result("SU",`Artskart-posten gir ikke nok miljøinformasjon til å vurdere ${measureInfo[measure].label.toLowerCase()}.`);
  switch(measure){
    case "clearcut":
      if(mobileObservation)return result("S2","Arten kan være relevant, men punktet dokumenterer ikke om observasjonen gjelder hekking, funksjonsområde eller et tilfeldig besøk.");
      if(forest||dead||old||soil||living)return result("S1","Tiltaket kan fjerne registrerte trær eller skogstrukturer og samtidig endre skogklima og skogbunn direkte.");
      if(wet)return result("S2","Relevansen avhenger av avstand, kantsone, avrenning og om hogsten påvirker fuktighetsforholdene.");
      break;
    case "selective":
      if(/barlind|levende individ/.test(text))return result("S1","Et konkret levende individ kan bli berørt direkte dersom det inngår i uttaket eller kjøresonen.");
      if(forest||dead||old||soil||living||wet)return result("S2","Selektiv hogst kan være relevant dersom vertstrær, substrat, kronedekke eller lokale fuktighetsforhold berøres.");
      break;
    case "thinning":
      if(forest||old||living||soil||dead)return result("S2","Tynning kan endre kronedekke, lys, fuktighet og vertstrær; virkningen avhenger av styrke og plassering.");
      if(wet)return result("S3","Tynning er normalt ikke direkte relevant dersom kantsonen og hydrologien ikke påvirkes.");
      break;
    case "youngForest":
      if(old||living||soil)return result("S2","Rydding kan påvirke vertstrær, skogbunn eller lokalt mikroklima dersom forekomsten ligger i tiltaksområdet.");
      if(forest)return result("S2","Skogtilknytningen er relevant, men posten dokumenterer ikke at ungskogpleie berører artens konkrete ressurs.");
      if(dead||wet)return result("S3","Tiltaket er normalt ikke direkte relevant så lenge død ved, kantsoner og hydrologi beholdes.");
      break;
    case "standingDead":
      if(mobileObservation&&dead)return result("S2","Død ved kan være en viktig næringsressurs, men observasjonens aktivitet og lokale funksjon må avklares før direkte relevans fastsettes.");
      if(dead)return result("S1","Uttak av døde trær eller vindfall kan fjerne registrert substrat eller næringsressurs direkte.");
      if(old||living||forest)return result("S2","Relevant dersom uttaket omfatter vertstrær eller åpner bestandet rundt forekomsten.");
      if(wet)return result("S3","Normalt ikke relevant uten kjøring eller uttak i kantsone og våtmark.");
      break;
    case "lyingDead":
      if(lying)return result("S1","Liggende død ved er dokumentert som artens substrat og kan bli fjernet direkte.");
      if(dead&&!standing)return result("S2","Posten viser dødvedtilknytning, men dokumenterer ikke sikkert at liggende ved er den berørte ressursen.");
      if(standing)return result("S3","Posten peker på stående død ved; et rent uttak av liggende ved er normalt ikke direkte relevant.");
      if(old||forest)return result("S2","Relevant dersom liggende ved inngår i artens lokale skogmiljø, men dette er ikke dokumentert i posten.");
      if(wet)return result("S3","Normalt ikke relevant uten kjøring eller fjerning av ved i kantsone og våtmark.");
      break;
    case "scarification":
      if(soil)return result("S1","Markberedning kan påvirke registrert kalkmiljø, skogbunn, røtter eller levende individ direkte.");
      if(wet||dead||old||forest)return result("S2","Relevansen avhenger av kjøresoner, blottlegging av jord og avstand til substrat eller fuktig livsmiljø.");
      break;
    case "ditching":
      if(mobileObservation&&wet)return result("S2","Vannmiljøet kan påvirkes, men punktobservasjonen dokumenterer ikke alene et fast funksjonsområde.");
      if(wet)return result("S1","Arten eller livsmiljøet er knyttet til fuktighet eller vann; tiltaket kan endre hydrologien direkte.");
      if(forest||dead||old||soil||living)return result("S2","Grøfting kan få indirekte betydning dersom dreneringen endrer fuktighet i skogmiljøet.");
      break;
    case "road":
      if(wet||forest||dead||old||soil||living)return result("S2","Virkningen avhenger av veglinje, fylling, skjæring, bekkekryssing og terrengkjøring nær forekomsten.");
      break;
    case "speciesChange":
      if(mobileObservation&&forest)return result("S2","Treslag og skogstruktur kan ha betydning, men punktet dokumenterer ikke alene artens lokale funksjonsområde.");
      if(forest||living||soil||old||dead)return result("S1","Endret treslag kan påvirke vertstrær, rotsymbioser, framtidig substrattilgang og skogklima direkte eller over tid.");
      if(wet)return result("S2","Normalt bare relevant dersom treslagsskiftet også endrer skygge, vannforbruk eller kantsone.");
      break;
    case "fertilizing":
      if(soil||wet||forest||dead||old||living)return result("S2","Tilførsel av næring eller kjemiske midler kan endre voksestedet; faktisk relevans avhenger av middel, dose og spredningsområde.");
      break;
    case "oldTrees":
      if(mobileObservation&&forest)return result("S2","Gamle trær kan inngå i artens funksjonsområde, men aktivitet eller bruk av det konkrete treet er ikke dokumentert.");
      if(old||living)return result("S1","Gamle, grove eller særskilte trær inngår i det registrerte livsmiljøet og kan bli berørt direkte.");
      if(dead||forest)return result("S2","Skogtilknytningen kan være relevant, men posten dokumenterer ikke sikkert avhengighet av et gammelt levende tre.");
      if(wet)return result("S3","Arten er primært knyttet til vann eller våtmark, ikke til gamle trær.");
      break;
  }
  return result("SU",`Det finnes ikke tilstrekkelig grunnlag i posten til å vurdere ${measureInfo[measure].label.toLowerCase()}.`);
}
